def _expand(
    value: str,
    section: str,
    sections: dict[str, dict[str, str]],
    resolve: callable,
) -> str:
    """Interpolate one value, using ``resolve`` for references."""
    parts: list[str] = []
    index = 0
    length = len(value)

    while index < length:
        char = value[index]
        if char != "$":
            parts.append(char)
            index += 1
            continue

        following = value[index + 1] if index + 1 < length else ""
        if following == "$":
            # A literal dollar sign; the result is not scanned again.
            parts.append("$")
            index += 2
            continue

        if following == "{":
            end = value.find("}", index + 2)
            if end != -1:
                parts.append(resolve(value[index + 2 : end], section))
                index = end + 1
                continue

        # Any other dollar sign is left alone.
        parts.append("$")
        index += 1

    return "".join(parts)


def _interpolate(sections: dict[str, dict[str, str]]) -> dict[str, dict[str, str]]:
    """Return a copy of ``sections`` with all values interpolated."""
    resolved: dict[tuple[str, str], str] = {}
    stack: list[tuple[str, str]] = []

    def resolve_key(section: str, key: str) -> str:
        token = (section, key)
        if token in stack:
            cycle = " -> ".join(f"{s}:{k}" for s, k in stack + [token])
            raise InterpolationError(f"interpolation cycle: {cycle}")
        if token in resolved:
            return resolved[token]

        stack.append(token)
        try:
            result = _expand(sections[section][key], section, sections, resolve_reference)
        finally:
            stack.pop()

        resolved[token] = result
        return result

    def resolve_reference(reference: str, section: str) -> str:
        if ":" in reference:
            reference_section, reference_key = reference.split(":", 1)
        else:
            reference_section, reference_key = section, reference
        reference_key = reference_key.lower()

        if reference_section not in sections:
            raise InterpolationError(f"missing section {reference_section!r}")
        if reference_key not in sections[reference_section]:
            raise InterpolationError(
                f"missing key {reference_key!r} in section {reference_section!r}"
            )
        return resolve_key(reference_section, reference_key)

    return {
        section: {key: resolve_key(section, key) for key in values}
        for section, values in sections.items()
    }


def parse(text: str) -> dict[str, dict[str, str]]:
    """Parse INI text."""
    sections: dict[str, dict[str, str]] = {}
    current_section: str | None = None
    continued: tuple[str, str] | None = None

    for lineno, line in enumerate(text.splitlines(), 1):
        stripped = line.strip()

        # Blank lines and comments are ignored and end any continuation.
        if not stripped or stripped.startswith(("#", ";")):
            continued = None
            continue

        # An indented line continues the preceding key's value.
        if continued is not None and line[:1].isspace():
            section, key = continued
            sections[section][key] += "\n" + stripped
            continue

        # Only a continuation is indentation-sensitive; everything else is
        # read after stripping it.
        continued = None

        if stripped.startswith("[") and stripped.endswith("]"):
            current_section = stripped[1:-1].strip()
            sections.setdefault(current_section, {})
            continue

        equals = stripped.find("=")
        colon = stripped.find(":")
        separators = [index for index in (equals, colon) if index != -1]
        if not separators:
            raise ParseError(lineno, "expected a section or key/value pair")

        separator = min(separators)
        key = stripped[:separator].strip().lower()
        value = stripped[separator + 1 :].strip()

        if not key:
            raise ParseError(lineno, "empty key")
        if current_section is None:
            raise ParseError(lineno, "key before any section")

        sections[current_section][key] = value
        continued = (current_section, key)

    return _interpolate(sections)

